floor_fn:
"""Checks if a chunk ended between the previous and current word.

    Args:
        prev_tag: previous chunk tag.
        tag: current chunk tag.
        prev_type: previous type.
        type_: current type.

    Returns:
        chunk_end: boolean.
    """
def end_of_chunk(prev_tag: Any, tag: Any, prev_type: Any, type_: Any) -> object {
    chunk_end = False;
    if (prev_tag == 'E') {
        chunk_end = True;
    }
    if (prev_tag == 'S') {
        chunk_end = True;
    }
    if ((prev_tag == 'B') and (tag == 'B')) {
        chunk_end = True;
    }
    if ((prev_tag == 'B') and (tag == 'S')) {
        chunk_end = True;
    }
    if ((prev_tag == 'B') and (tag == 'O')) {
        chunk_end = True;
    }
    if ((prev_tag == 'I') and (tag == 'B')) {
        chunk_end = True;
    }
    if ((prev_tag == 'I') and (tag == 'S')) {
        chunk_end = True;
    }
    if ((prev_tag == 'I') and (tag == 'O')) {
        chunk_end = True;
    }
    if ((prev_tag != 'O') and (prev_tag != '.') and (prev_type != type_)) {
        chunk_end = True;
    }
    return chunk_end;
}

test_blocks:
test "t0" {
    assert (end_of_chunk('O', 'B', None, 'B') == False);;
}

test "t1" {
    assert (end_of_chunk('E', 'E', 'LOC', 'I') == True);;
}

test "t2" {
    assert (end_of_chunk('I', 'B', 'PER', 'ORG') == True);;
}

test "t3" {
    assert (end_of_chunk(None, None, None, None) == False);;
}

test "t4" {
    assert (end_of_chunk('B', 'B', 'LOC', 'PER') == True);;
}

test "t5" {
    assert (end_of_chunk('O', 'O', 'LOC', 'PER') == False);;
}

test "t6" {
    assert (end_of_chunk('B', 'O', 'PER', 'ORG') == True);;
}

test "t7" {
    assert (end_of_chunk(None, 'B', None, 'B') == True);;
}

test "t8" {
    assert (end_of_chunk('B', 'E', 'PER', 'I') == True);;
}
